  private parseRole(
    raw?: string,
  ): StaffRole | undefined {
    if (
      raw === undefined ||
      raw === '' ||
      raw === 'ALL'
    ) {
      return undefined;
    }

    const allowed: StaffRole[] = [
      'CAREGIVER',
      'NURSE',
      'SUPERVISOR',
      'CARE_MANAGER',
    ];

    if (
      !allowed.includes(
        raw as StaffRole,
