    result: PromiseSettledResult<any>,
  ): SettledDomain {
    if (result.status === 'rejected') {
      return {
        rows: [],
        availability: 'UNAVAILABLE',
        total: 0,
      };
    }

    const rows =
      Array.isArray(result.value?.rows)
