    @Headers('x-actor-role')
    actorRole?: string,

    @Body()
    body: {
      actorId?: string;
      actorRole?: string;
      accessScope?: string;
      effectiveFrom?: string;
      effectiveTo?: string | null;
    } = {},
  ) {
    return this.service.createAssignment(
      residentId,
      {
        actorId,
        actorRole,
      },
      body,
    );
  }

