    actorId?: string,

    @Headers('x-actor-role')
    actorRole?: string,

    @Body()
    body: {
      revocationReason?: string;
    } = {},
  ) {
    return this.service.revokeAssignment(
      assignmentId,
      {
        actorId,
        actorRole,
      },
      body,
    );
  }
}

